##############################################################################
### Step 3. Manual simulation using 10 runs 
###         = This manual simulation is only for illustrative purposes
### Note: A real simulation can be done with "perform_monte_carlo_simulation"
###       (= This is shown in Example Experiment 8)
##############################################################################

sampled_activity_set = {}
list_simulated_schedules = []

for run_index, rd in enumerate(real_durations, start=1):

    # Step 1. Create sampled_activity_set for this run
    sampled_activity_set = {
        activity: (rd[activity], 0)  # duration from rd, cost = 0 (irrelevant for this experiment)
        for activity in activity_names.keys()
    }
    print("sampled_activity_set = ", sampled_activity_set)

    # Step 2. Simulate the new RCP schedule (with real durations and costs and resources)
    
    # Step 2.1. Set the priority list equal to the start times of the resource-feasible baseline schedule
    priority_list = [(key, values[0][3]) for key, values in activity_schedule.items()]

    # Step 2.2. Generate a sampled schedule with the new durations 
    # (no costs are calculated, only time)
    # (the serial SGS cannot be used, only the parallel SGS)          
    total_duration, total_cost, simulated_schedule, lss_test, _ = parallel_sgs(
        activity_names,
        sampled_activity_set,
        activity_dependencies,
        resource_requirements, # not in CPM simulation
        resource_availability, # not in CPM simulation
        priority_list,
        debugInfo = False
    )
    
    # Step 3. Print the simulated resource-feasible project progress
    print("Total Project Duration of the Simulated Schedule = ", total_duration)
    plot_resource_profiles(simulated_schedule, resource_availability, resource_requirements, legend_size = 0, title_size = 0, showName = False)    
       
    # Step 4. Add the total project duration, total project cost and simulated schedule to the list_simulated_schedules
    list_simulated_schedules.append((total_duration, total_cost, simulated_schedule))
    
# Put the list_simulated_schedules into a dataframe (necessary for the sensitity calculations)
simulated_schedules = pd.DataFrame(list_simulated_schedules, columns=['Total Duration', 'Total Cost', 'Simulated Schedules'])

# Print the simulated project duration values
print("Simulated data:")
print(f"  - Average duration = {simulated_schedules['Total Duration'].mean():.2f}")
print(f"  - Standard deviation = {simulated_schedules['Total Duration'].std():.2f}")
print(f"  - Minimum duration = {simulated_schedules['Total Duration'].min():.2f}")
print(f"  - Maximum duration = {simulated_schedules['Total Duration'].max():.2f}")

